// Set the public page and request region. Keep API keys in n8n credentials.
const config = {
  url: 'https://www.scrapeless.com/en',
  country: 'US',
  max_body_characters: 20000,
  max_links: 100,
};
if (!/^https?:\/\/[^\s@]+$/i.test(config.url)) throw new Error('Enter an absolute public HTTP(S) URL without credentials.');
if (!/^[A-Z]{2}$/.test(config.country)) throw new Error('Use a supported two-letter country code.');
return [{ json: config }];

const raw = $input.first().json;
if (raw.code !== 200 || typeof raw.data !== 'string' || !raw.data.trim()) {
  throw new Error('Web Unlocker did not return a successful HTML response. Inspect the private execution.');
}
if (!/<(?:html|body|main|article)\b/i.test(raw.data)) {
  throw new Error('The response is not an HTML document.');
}
return [{ json: { html: raw.data, html_characters: raw.data.length } }];

const page = $input.first().json;
const config = $('Configure Page').first().json;
const clean = value => typeof value === 'string' ? value.replace(/\s+/g, ' ').trim() : '';
const title = clean(page.title);
const fullBody = clean(page.body);
if (!title || fullBody.length < 100) throw new Error('No usable title/body was extracted. Check the page, selectors, redirects, or access challenges.');
const headings = [...new Set((page.headings || []).map(clean).filter(Boolean))];
const links = [...new Set((page.links || []).map(clean).filter(v => v && !/^(?:javascript:|data:|mailto:|tel:|#)/i.test(v)))].slice(0, config.max_links);
const bodyText = fullBody.slice(0, config.max_body_characters);
const report = {
  target_url: config.url,
  page_title: title,
  description: clean(page.description),
  headings,
  body_text: bodyText,
  links,
  extraction: {
    html_characters: $('Validate HTML').first().json.html_characters,
    extracted_body_characters: fullBody.length,
    exported_body_characters: bodyText.length,
    body_truncated: bodyText.length < fullBody.length,
    exported_links: links.length,
    max_links: config.max_links,
    links_are_raw_hrefs: true,
  },
};
const md = [
  '# ' + title,
  '',
  'Source: ' + config.url,
  '',
  report.description,
  '',
  '## Headings',
  ...headings.map(h => '- ' + h),
  '',
  '## Page text',
  bodyText,
  '',
  '## Links (original href values)',
  ...links.map(url => '- ' + url),
  '',
  '## Extraction notes',
  '- Extracted page text; no AI-generated summary.',
  '- Body text truncated: ' + report.extraction.body_truncated,
  '- Exported links: ' + links.length + ' (limit ' + config.max_links + ').',
].join('\n');
return [{ json: { ...report, report_markdown: md } }];
